contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: artId to create, and ether to send along (must be >= artFee to exercise forwarding and refund behavior)
    function run(uint256 artId, uint256 value) public payable {
        require(address(this).balance >= value, "insufficient balance for test");

        // read pre-state
        uint256 beforeCounter = c.tokenIdCounter();
        // protocol fee destination and artCreateFee are observable via phiFactory through c.contractURI()/phiFactory? -- but phiFactory is not directly accessible.
        // We can observe address(c).balance to check transfer effects and token mappings via getTokenIdFromFactoryArtId

        // call: must be made by this contract as if caller is phiFactory; the real C expects createArtFromFactory to be called only by phiFactory.
        // However the checker deploys C and passes it into this test; we cannot change msg.sender that C expects. To still make a meaningful property, we attempt the call and record whether it reverts.
        bool reverted;
        try c.createArtFromFactory{value: value}(artId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 afterCounter = c.tokenIdCounter();
        uint256 mappedTokenId = c.getTokenIdFromFactoryArtId(artId);
        // Observed balances of c and this contract
        uint256 cBal = address(c).balance;
        uint256 meBal = address(this).balance;

        // General rule to assert:
        // If the call did NOT revert, then:
        //  - mappedTokenId must be non-zero and equal to a token id < afterCounter and >= beforeCounter
        //  - tokenIdCounter must have increased by at least 1
        // If the call DID revert, no guarantees (so we assert implication)

        assert(reverted || (
            mappedTokenId != 0 &&
            // tokenId was created in the expected range: created id is >= beforeCounter && < afterCounter
            (mappedTokenId >= beforeCounter && mappedTokenId < afterCounter) &&
            // counter incremented (at least by 1)
            (afterCounter > beforeCounter)
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require caller supplies some ether (value) to forward; keep it bounded to avoid huge numbers
    function run(uint256 artId, uint256 value) public payable {
        require(value > 0 && value <= 1 ether, "value bounds");
        require(address(this).balance >= value, "insufficient balance for test");

        uint256 before = c.tokenIdCounter();

        bool reverted;
        try c.createArtFromFactory{value: value}(artId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.tokenIdCounter();

        // Assert: if the call succeeded (didn't revert) then tokenIdCounter strictly increased
        assert(reverted || after > before);
    }

    receive() external payable {}
}

